<script setup lang="ts">
import {computed,ref,onMounted,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,user,message,notify,refreshAuth,type Member} from '../api'
import {useAdminAccess,roleLabels,adminDate,canManage} from '../composables/admin'
import Icon from '../components/Icon.vue'
import AdminDialog from '../components/AdminDialog.vue'
type Account=Member&{createdAt:string}
type PublicAccount={id:number;username:string;penName:string;memberIds:number[]}
type PermissionEditor={id:number;username:string;role:string;permissions:Record<string,boolean>}
const {isSuper}=useAdminAccess(),route=useRoute(),router=useRouter()
const accounts=ref<Account[]>([]),publicAccounts=ref<PublicAccount[]>([]),catalog=ref<Record<string,string>>({})
const loading=ref(true),error=ref(''),dialogError=ref(''),saving=ref(false),opening=ref<number|null>(null)
const search=ref(''),role=ref(''),page=ref(1),memberSearch=ref('')
const editing=ref<PermissionEditor|null>(null),publicEditing=ref<PublicAccount|null>(null)
const deleteTarget=ref<Account|null>(null),deleteError=ref('')
function canDelete(a:Account){return isSuper.value&&a.id!==(user.value?.actorId||user.value?.id)}
async function removeAccount(){if(!deleteTarget.value||saving.value)return;saving.value=true;deleteError.value='';try{await api.delete(`/admin/accounts/${deleteTarget.value.id}`);deleteTarget.value=null;notify('用户已删除，登录及公用身份授权已撤销');await load()}catch(e){deleteError.value=message(e)}finally{saving.value=false}}
const view=computed(()=>route.query.view==='public'?'public':'personal')
const personal=computed(()=>accounts.value.filter(a=>a.accountType!=='PUBLIC'))
const filtered=computed(()=>personal.value.filter(a=>(!role.value||a.role===role.value)&&`${a.username} ${a.penName} ${a.qqNumber||''}`.toLowerCase().includes(search.value.trim().toLowerCase())))
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/12)))
const visible=computed(()=>filtered.value.slice((page.value-1)*12,page.value*12))
const members=computed(()=>personal.value.filter(a=>`${a.username} ${a.penName}`.toLowerCase().includes(memberSearch.value.trim().toLowerCase())))
const restricted=computed(()=>personal.value.filter(a=>a.role==='RESTRICTED').length)
watch([search,role],()=>page.value=1)
watch(pages,()=>page.value=Math.min(page.value,pages.value))
function selectView(value:string){void router.replace({query:value==='public'?{view:'public'}:{}})}
function canEdit(a:Account){return isSuper.value||!['ADMIN','SUPER_ADMIN'].includes(a.role)}
async function load(){loading.value=true;error.value='';try{const [a,p,s]=await Promise.all([api.get('/admin/accounts'),api.get('/admin/public-accounts'),api.get('/admin/settings')]);accounts.value=a.data;publicAccounts.value=p.data;catalog.value=s.data.permissionCatalog}catch(e){error.value=message(e)}finally{loading.value=false}}
async function edit(a:Account){if(opening.value!==null)return;opening.value=a.id;dialogError.value='';try{editing.value=(await api.get(`/admin/accounts/${a.id}/permissions`)).data}catch(e){error.value=message(e)}finally{opening.value=null}}
watch(()=>editing.value?.role,(next,previous)=>{if(!editing.value||!previous||next===previous)return;if(next==='RESTRICTED'||(previous==='RESTRICTED'&&next==='MEMBER'))for(const key of Object.keys(catalog.value))editing.value.permissions[key]=next==='MEMBER'})
async function savePermissions(){if(!editing.value||saving.value)return;saving.value=true;dialogError.value='';try{await api.put(`/admin/accounts/${editing.value.id}/permissions`,editing.value);editing.value=null;notify('账户角色与权限已更新');await refreshAuth();if(canManage('accounts'))await load();else await router.replace(canManage('overview')?'/admin':'/account')}catch(e){dialogError.value=message(e)}finally{saving.value=false}}
function editPublic(a:PublicAccount){publicEditing.value={...a,memberIds:[...a.memberIds]};memberSearch.value='';dialogError.value=''}
async function savePublic(){if(!publicEditing.value||saving.value)return;saving.value=true;dialogError.value='';try{await api.put(`/admin/public-accounts/${publicEditing.value.id}/members`,{memberIds:publicEditing.value.memberIds});publicEditing.value=null;notify('公用账户授权名单已更新');await load()}catch(e){dialogError.value=message(e)}finally{saving.value=false}}
onMounted(load)
</script>
<template>
  <header class="admin-page-heading"><div><p class="admin-kicker">ACCOUNT MANAGEMENT</p><h1>账户管理</h1><p>管理社员身份与使用权限，让每个账户各司其职。</p></div><button class="button secondary small" :disabled="loading" @click="load"><Icon name="RefreshCw" :size="15"/>刷新名单</button></header>
  <div class="admin-metrics admin-metrics-compact"><div class="admin-metric"><span>个人账户</span><strong>{{loading||error?'—':personal.length}}</strong></div><div class="admin-metric"><span>受限账户</span><strong>{{loading||error?'—':restricted}}</strong></div><div class="admin-metric"><span>公用账户</span><strong>{{loading||error?'—':publicAccounts.length}}</strong></div></div>
  <div class="admin-subnav" aria-label="账户分类"><button :class="{selected:view==='personal'}" @click="selectView('personal')">个人账户<span>{{personal.length}}</span></button><button :class="{selected:view==='public'}" @click="selectView('public')">公用账户<span>{{publicAccounts.length}}</span></button></div>
  <p v-if="error" class="error-message" role="alert">{{error}} <button @click="load">重新加载</button></p>
  <template v-if="view==='personal'">
    <form class="admin-filters" @submit.prevent="page=1"><label class="admin-search-field"><Icon name="Search" :size="17"/><input v-model="search" aria-label="搜索账户" placeholder="搜索笔名、账号或 QQ 号"/></label><label><span class="sr-only">按角色筛选</span><select v-model="role" aria-label="按角色筛选"><option value="">全部角色</option><option v-for="(label,key) in roleLabels" :key="key" :value="key">{{label}}</option></select></label><span class="admin-result-count">共 {{filtered.length}} 个账户</span></form>
    <div class="admin-table-wrap"><table class="admin-table admin-accounts-table"><thead><tr><th>社员 / 账号</th><th>角色</th><th>QQ 号</th><th>加入时间</th><th class="admin-cell-end">操作</th></tr></thead><tbody v-if="!loading&&!error"><tr v-for="a in visible" :key="a.id"><td><div class="admin-person"><span class="admin-letter-avatar">{{(a.penName||a.username).slice(0,1)}}</span><div><strong>{{a.penName||a.username}}</strong><small>{{a.username}}</small></div></div></td><td><span class="admin-badge" :class="{restricted:a.role==='RESTRICTED',privileged:['ADMIN','SUPER_ADMIN'].includes(a.role)}">{{roleLabels[a.role]||a.role}}</span></td><td>{{a.qqNumber||'—'}}</td><td class="admin-muted">{{adminDate(a.createdAt)}}</td><td class="admin-cell-end"><button v-if="canEdit(a)" class="admin-inline-link" :disabled="opening!==null" @click="edit(a)">{{opening===a.id?'加载中…':'配置权限'}}</button><span v-else class="admin-muted">仅超级管理员可管理</span><button v-if="canDelete(a)" class="admin-inline-link admin-danger-link" style="margin-left:14px" @click="deleteTarget=a;deleteError=''">删除用户</button></td></tr></tbody></table><div v-if="loading" class="admin-empty">正在加载账户名单…</div><div v-else-if="!error&&!filtered.length" class="admin-empty"><Icon name="Users" :size="28"/><h3>没有匹配的账户</h3><p>试试其他关键词，或重置角色筛选。</p><button class="admin-inline-link" @click="search='';role=''">重置筛选</button></div></div>
    <div class="admin-table-footer"><p>管理员可管理社员权限；管理员角色仅由超级管理员调整。</p><div class="admin-pagination"><button :disabled="page<=1" aria-label="上一页账户" @click="page--"><Icon name="ChevronLeft" :size="16"/></button><span>{{page}} / {{pages}}</span><button :disabled="page>=pages" aria-label="下一页账户" @click="page++"><Icon name="ChevronRight" :size="16"/></button></div></div>
  </template>
  <template v-else><div class="admin-info"><Icon name="ShieldCheck" :size="19"/><p>授权社员可切换使用公用身份，每个公用账户最多同时由 5 人使用。{{isSuper?'点击“管理授权”调整使用名单。':'公用账户授权由超级管理员配置。'}}</p></div><p v-if="loading" class="admin-empty">正在加载公用账户…</p><div v-else-if="!error" class="admin-public-accounts"><article v-for="a in publicAccounts" :key="a.id" class="admin-surface"><div class="admin-public-heading"><span class="admin-entry-icon"><Icon name="ShieldCheck" :size="24"/></span><span class="admin-badge published">公用身份</span></div><h2>{{a.penName}}</h2><p class="admin-muted">{{a.username}}</p><div class="admin-public-bottom"><span>{{a.memberIds.length}} 人已授权</span><button class="admin-inline-link" @click="editPublic(a)">{{isSuper?'管理授权':'查看名单'}} <Icon name="ArrowRight" :size="14"/></button></div></article><p v-if="!publicAccounts.length" class="admin-empty">暂无公用账户。</p></div></template>
  <AdminDialog v-if="editing" :title="`配置权限 · ${editing.username}`" :busy="saving" @close="editing=null"><form class="admin-form" @submit.prevent="savePermissions"><p v-if="dialogError" class="error-message" role="alert">{{dialogError}}</p><label>账户角色<select v-model="editing.role"><option value="MEMBER">社员</option><option value="RESTRICTED">受限社员</option><template v-if="isSuper"><option value="ADMIN">管理员</option><option value="SUPER_ADMIN">超级管理员</option></template></select></label><div class="admin-form-section"><h3>功能权限</h3><p>受限社员默认关闭全部功能，可按需恢复。管理员拥有全部功能权限。</p><label v-for="(label,code) in catalog" :key="code" class="admin-checkbox"><input v-model="editing.permissions[code]" type="checkbox" :disabled="['ADMIN','SUPER_ADMIN'].includes(editing.role)"/>{{label}}</label></div><footer class="admin-form-actions"><button type="button" class="button secondary" :disabled="saving" @click="editing=null">取消</button><button class="button" :disabled="saving">{{saving?'保存中…':'保存权限'}}</button></footer></form></AdminDialog>
  <AdminDialog v-if="publicEditing" :title="`${publicEditing.penName} · 授权名单`" :busy="saving" @close="publicEditing=null"><form class="admin-form" @submit.prevent="savePublic"><p v-if="dialogError" class="error-message" role="alert">{{dialogError}}</p><p class="admin-muted">已选择 {{publicEditing.memberIds.length}} 人。授权后，社员可切换至此公用身份。</p><label class="admin-search-field"><Icon name="Search" :size="17"/><input v-model="memberSearch" aria-label="搜索授权社员" placeholder="搜索社员笔名或账号"/></label><div class="admin-member-picker"><label v-for="a in members" :key="a.id" class="admin-checkbox"><input v-model="publicEditing.memberIds" type="checkbox" :value="a.id" :disabled="!isSuper"/><span>{{a.penName}}<small>{{a.username}} · {{roleLabels[a.role]}}</small></span></label><p v-if="!members.length" class="admin-empty">没有匹配的社员。</p></div><footer class="admin-form-actions"><button type="button" class="button secondary" :disabled="saving" @click="publicEditing=null">关闭</button><button v-if="isSuper" class="button" :disabled="saving">{{saving?'保存中…':'保存授权名单'}}</button></footer></form></AdminDialog>
  <AdminDialog v-if="deleteTarget" :title="`删除用户 · ${deleteTarget.username}`" :busy="saving" @close="deleteTarget=null"><div class="admin-confirm-copy"><h3>{{deleteTarget.penName}}（{{deleteTarget.username}}）</h3><p>删除后，该用户将从账户名单移除，无法再登录，公用身份授权及已记住的设备同步撤销。保留历史作品、署名和审计记录。</p></div><p v-if="deleteError" class="error-message" role="alert">{{deleteError}}</p><footer class="admin-form-actions"><button class="button secondary" :disabled="saving" @click="deleteTarget=null">取消</button><button class="button admin-danger-button" :disabled="saving" @click="removeAccount">确认删除用户</button></footer></AdminDialog>
</template>
